import{_ as t}from"./chunks/cynefin-OW5HDTMX.rPCZ-tep.js";import{o as a,c as i,a as s}from"./chunks/mermaid.C1W4YCqa.js";import"./chunks/mermaid-utils.B0bJactl.js";import"./chunks/mermaid-graph.C5JX3QLV.js";import"./chunks/mermaid-layout.DzVnZVT_.js";const m=JSON.parse('{"title":"Environment variables","description":"","frontmatter":{},"headers":[],"relativePath":"reference/environment.md","filePath":"reference/environment.md"}'),o={name:"reference/environment.md"};function d(r,e,h,n,c,l){return a(),i("div",null,[...e[0]||(e[0]=[s('<h1 id="environment-variables" tabindex="-1">Environment variables <a class="header-anchor" href="#environment-variables" aria-label="Permalink to &quot;Environment variables&quot;">​</a></h1><p><code>github-code-search</code> reads the following environment variables at runtime.</p><h2 id="reference" tabindex="-1">Reference <a class="header-anchor" href="#reference" aria-label="Permalink to &quot;Reference&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Variable</th><th>Required</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>GITHUB_TOKEN</code></td><td>✅¹</td><td>—</td><td>GitHub personal access token. Used to authenticate API calls. See <a href="/github-code-search/v2/getting-started/">Prerequisites</a>.</td></tr><tr><td><code>GCS_DEFAULT_ORG</code></td><td>❌</td><td>—</td><td>Default value for <code>--org</code> when the flag is omitted. An explicit <code>--org</code> always takes precedence. See <a href="/github-code-search/v2/reference/cli-options.html">CLI options</a>.</td></tr><tr><td><code>CI</code></td><td>❌</td><td><code>false</code></td><td>Set to <code>true</code> to disable the interactive TUI and print results directly to stdout. Automatically set by GitHub Actions, GitLab CI, CircleCI and most CI platforms.</td></tr><tr><td><code>GITHUB_CODE_SEARCH_CACHE_DIR</code></td><td>❌</td><td>OS-dependent (below)</td><td>Override the directory used to cache the team list when <code>--group-by-team-prefix</code> is set.</td></tr></tbody></table><p>¹ Required for the search commands, unless the <a href="https://cli.github.com/" target="_blank" rel="noreferrer">GitHub CLI</a> is installed and authenticated — <code>gh auth token</code> is used as a fallback. The <code>upgrade</code> subcommand never requires a token; it only uses one opportunistically (higher GitHub API rate limits) when available.</p><h2 id="github-token" tabindex="-1"><code>GITHUB_TOKEN</code> <a class="header-anchor" href="#github-token" aria-label="Permalink to &quot;`GITHUB_TOKEN`&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light-high-contrast github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#A0111F;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#0E1116;--shiki-dark:#E1E4E8;"> GITHUB_TOKEN</span><span style="--shiki-light:#A0111F;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#0E1116;--shiki-dark:#E1E4E8;">ghp_xxxxxxxxxxxxxxxxxxxx</span></span></code></pre></div><p>Add this to your shell profile (<code>~/.zshrc</code>, <code>~/.bashrc</code>, <code>~/.config/fish/config.fish</code>, …) to persist it across sessions. The required scopes depend on your use case:</p><table tabindex="0"><thead><tr><th>Scope</th><th>When needed</th></tr></thead><tbody><tr><td><code>repo</code></td><td>Searching <strong>private</strong> repositories</td></tr><tr><td><code>public_repo</code></td><td>Searching public repositories only</td></tr><tr><td><code>read:org</code></td><td>Using <a href="/github-code-search/v2/usage/team-grouping.html"><code>--group-by-team-prefix</code></a></td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Already using the GitHub CLI?</p><p>If <code>GITHUB_TOKEN</code> isn&#39;t set and <a href="https://cli.github.com/" target="_blank" rel="noreferrer"><code>gh</code></a> is installed and authenticated (<code>gh auth login</code>), <code>github-code-search</code> automatically retrieves a token via <code>gh auth token</code> — no extra setup needed. Applies to the search commands and the <code>upgrade</code> subcommand.</p></div><h2 id="gcs-default-org" tabindex="-1"><code>GCS_DEFAULT_ORG</code> <a class="header-anchor" href="#gcs-default-org" aria-label="Permalink to &quot;`GCS_DEFAULT_ORG`&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light-high-contrast github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#A0111F;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#0E1116;--shiki-dark:#E1E4E8;"> GCS_DEFAULT_ORG</span><span style="--shiki-light:#A0111F;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#0E1116;--shiki-dark:#E1E4E8;">my-org</span></span>\n<span class="line"><span style="--shiki-light:#702C00;--shiki-dark:#B392F0;">github-code-search</span><span style="--shiki-light:#032563;--shiki-dark:#9ECBFF;"> &quot;useFeatureFlag&quot;</span><span style="--shiki-light:#66707B;--shiki-dark:#6A737D;">   # --org my-org is implied</span></span></code></pre></div><p>Useful when you mostly (or only) search a single organization — set it once in your shell profile and omit <code>--org</code> on every call. Passing <code>--org</code> explicitly always overrides it.</p><h2 id="ci" tabindex="-1"><code>CI</code> <a class="header-anchor" href="#ci" aria-label="Permalink to &quot;`CI`&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light-high-contrast github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#0E1116;--shiki-dark:#E1E4E8;">CI</span><span style="--shiki-light:#A0111F;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032563;--shiki-dark:#9ECBFF;">true</span><span style="--shiki-light:#702C00;--shiki-dark:#B392F0;"> github-code-search</span><span style="--shiki-light:#032563;--shiki-dark:#9ECBFF;"> &quot;useFeatureFlag&quot;</span><span style="--shiki-light:#023B95;--shiki-dark:#79B8FF;"> --org</span><span style="--shiki-light:#032563;--shiki-dark:#9ECBFF;"> fulll</span></span></code></pre></div><p>Equivalent to passing <code>--no-interactive</code>. In GitHub Actions this variable is set automatically — no extra configuration needed.</p><h2 id="github-code-search-cache-dir" tabindex="-1"><code>GITHUB_CODE_SEARCH_CACHE_DIR</code> <a class="header-anchor" href="#github-code-search-cache-dir" aria-label="Permalink to &quot;`GITHUB_CODE_SEARCH_CACHE_DIR`&quot;">​</a></h2><p>Overrides the default OS cache directory used to store the team list (24 h TTL). Useful in restricted environments or when you want to share the cache across users.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light-high-contrast github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#0E1116;--shiki-dark:#E1E4E8;">GITHUB_CODE_SEARCH_CACHE_DIR</span><span style="--shiki-light:#A0111F;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032563;--shiki-dark:#9ECBFF;">/tmp/gcs-cache</span><span style="--shiki-light:#702C00;--shiki-dark:#B392F0;"> \\</span></span>\n<span class="line"><span style="--shiki-light:#032563;--shiki-dark:#9ECBFF;">  github-code-search</span><span style="--shiki-light:#032563;--shiki-dark:#9ECBFF;"> &quot;useFeatureFlag&quot;</span><span style="--shiki-light:#023B95;--shiki-dark:#79B8FF;"> --org</span><span style="--shiki-light:#032563;--shiki-dark:#9ECBFF;"> fulll</span><span style="--shiki-light:#023B95;--shiki-dark:#79B8FF;"> --group-by-team-prefix</span><span style="--shiki-light:#032563;--shiki-dark:#9ECBFF;"> squad-</span></span></code></pre></div><h3 id="default-cache-locations" tabindex="-1">Default cache locations <a class="header-anchor" href="#default-cache-locations" aria-label="Permalink to &quot;Default cache locations&quot;">​</a></h3><table tabindex="0"><thead><tr><th>OS</th><th>Default path</th></tr></thead><tbody><tr><td>macOS</td><td><code>~/Library/Caches/github-code-search/</code></td></tr><tr><td>Linux</td><td><code>$XDG_CACHE_HOME/github-code-search/</code> or <code>~/.cache/github-code-search/</code></td></tr><tr><td>Windows</td><td><code>%LOCALAPPDATA%\\github-code-search\\</code></td></tr></tbody></table>',21)])])}const y=t(o,[["render",d]]);export{m as __pageData,y as default};
